<?php
require_once __DIR__.'/functions.php';
function insert_ranking(array $r):bool{$p=db();$q=$p->prepare('SELECT id FROM ranking_bodies WHERE short_name=?');$q->execute([trim($r['ranking_body_short_name']??'')]);$id=$q->fetchColumn();if(!$id)return false;$g=trim((string)($r['global_rank']??''));$ph=trim((string)($r['ph_rank']??''));$q=$p->prepare('INSERT INTO rankings(ranking_body_id,year,category,global_rank,rank_value,ph_rank,ph_rank_value,note) VALUES(?,?,?,?,?,?,?,?)');return $q->execute([$id,(int)($r['year']??0),($r['category']??'')?:null,($g!=='')?$g:null,parse_rank_to_value($g),($ph!=='')?$ph:null,parse_rank_to_value($ph),trim((string)($r['note']??''))]);}
function insert_breakdown(array $r):bool{$p=db();$q=$p->prepare('SELECT id FROM ranking_bodies WHERE short_name=?');$q->execute([trim($r['ranking_body_short_name']??'')]);$id=$q->fetchColumn();$item=trim((string)($r['item_label']??''));if(!$id||$item==='')return false;$rd=trim((string)($r['rank_display']??''));$q=$p->prepare('INSERT INTO ranking_breakdowns(ranking_body_id,year,group_label,item_label,rank_display,rank_value,note) VALUES(?,?,?,?,?,?,?)');return $q->execute([$id,(int)($r['year']??0),($r['group_label']??'')?:null,$item,($rd!=='')?$rd:null,parse_rank_to_value($rd),trim((string)($r['note']??''))]);}
function insert_college(array $r):bool{$n=trim((string)($r['name']??''));$c=trim((string)($r['short_code']??''));if($n===''||$c==='')return false;$q=db()->prepare('INSERT INTO colleges(name,short_code,contribution_percent,year) VALUES(?,?,?,?)');return $q->execute([$n,$c,(float)($r['contribution_percent']??0),(int)($r['year']??0)]);}
function insert_program(array $r):bool{$n=trim((string)($r['name']??''));$cc=trim((string)($r['college_short_code']??''));if($n===''||$cc==='')return false;$q=db()->prepare('SELECT id FROM colleges WHERE short_code=? ORDER BY year DESC LIMIT 1');$q->execute([$cc]);$id=$q->fetchColumn();if(!$id)return false;$q=db()->prepare('INSERT INTO programs(name,college_id,national_rank,score,movement,year) VALUES(?,?,?,?,?,?)');return $q->execute([$n,$id,(int)($r['national_rank']??0),(float)($r['score']??0),(int)($r['movement']??0),(int)($r['year']??0)]);}
function insert_accreditation(array $r):bool{$n=trim((string)($r['program_name']??''));$c=trim((string)($r['criterion']??''));if($n===''||$c==='')return false;$s=trim((string)($r['score']??''));$q=db()->prepare('INSERT INTO accreditations(program_name,accrediting_body,year,assessment_date,criterion,score,numeric_score) VALUES(?,?,?,?,?,?,?)');return $q->execute([$n,trim((string)($r['accrediting_body']??'AUN-QA'))?:'AUN-QA',(int)($r['year']??0),($r['assessment_date']??'')?:null,$c,$s!==''?$s:null,is_numeric($s)?(float)$s:null]);}
